import{_ as a,o as e,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const f=JSON.parse('{"title":"45. Buffered I/O with fgets and fputs","description":"The Little Book of C — 45. Buffered I/O with fgets and fputs","frontmatter":{"title":"45. Buffered I/O with fgets and fputs","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Input Output and Files"],"description":"The Little Book of C — 45. Buffered I/O with fgets and fputs","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":45,"sidebarWeight":45,"lang":"en-US","alternateEn":"/posts/c教程/en-US/05-Input Output and Files/045-Buffered IO with fgets and fputs","alternateZh":"/posts/c教程/zh-CN/05-输入输出与文件/045-Buffered IO with fgets and fputs"},"headers":[],"relativePath":"posts/c教程/en-US/05-Input Output and Files/045-Buffered IO with fgets and fputs.md","filePath":"posts/c教程/en-US/05-Input Output and Files/045-Buffered IO with fgets and fputs.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/05-Input Output and Files/045-Buffered IO with fgets and fputs.md"};function p(o,s,l,r,d,u){return e(),n("div",null,[...s[0]||(s[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/05-输入输出与文件/045-Buffered IO with fgets and fputs)</p><p>When your program reads and writes data, it doesn’t always go directly to disk or the terminal, instead, it uses buffers. Buffers are small chunks of memory that temporarily hold data, improving performance by reducing how often the system has to perform slow I/O operations.</p><p>C’s Standard I/O library (<code>&lt;stdio.h&gt;</code>) handles this automatically for you. In this section, you’ll learn how buffering works and how to use<code>fgets</code>,<code>fputs</code>, and related functions to manage it effectively.</p><h4 id="what-is-buffered-i-o" tabindex="-1">What Is Buffered I/O? <a class="header-anchor" href="#what-is-buffered-i-o" aria-label="Permalink to &quot;What Is Buffered I/O?&quot;">​</a></h4><p>Instead of reading or writing one character at a time, the C library:</p><ul><li>Fills a buffer (for input) or</li><li>Collects a batch of characters (for output)</li></ul><p>When the buffer is full or flushed, data moves between your program and the file or terminal.</p><p>This is why sometimes<code>printf()</code> output doesn’t appear immediately, it’s waiting in a buffer until a newline or flush occurs.</p><h4 id="input-fgets" tabindex="-1">Input: fgets() <a class="header-anchor" href="#input-fgets" aria-label="Permalink to &quot;Input: fgets()&quot;">​</a></h4><p><code>fgets()</code> reads a full line from a stream (including spaces) and stores it in a string.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char *fgets(char *str, int size, FILE *stream);</span></span></code></pre></div><ul><li><code>str</code>: where to store the line</li><li><code>size</code>: maximum number of characters to read (including<code>\\0</code>)</li><li><code>stream</code>: where to read from (e.g.<code>stdin</code> or a file pointer)</li></ul><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char line[100];</span></span>
<span class="line"><span>    printf(&quot;Enter a sentence: &quot;);</span></span>
<span class="line"><span>    if (fgets(line, sizeof(line), stdin))</span></span>
<span class="line"><span>        printf(&quot;You said: %s&quot;, line);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Input:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C is beautiful.</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You said: C is beautiful.</span></span></code></pre></div><p>If the input exceeds the buffer,<code>fgets</code> stops reading after<code>size - 1</code> characters to prevent overflow, and automatically null-terminates the string.</p><h4 id="output-fputs" tabindex="-1">Output: fputs() <a class="header-anchor" href="#output-fputs" aria-label="Permalink to &quot;Output: fputs()&quot;">​</a></h4><p><code>fputs()</code> writes a string to a stream.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int fputs(const char *str, FILE *stream);</span></span></code></pre></div><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *fp = fopen(&quot;output.txt&quot;, &quot;w&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        perror(&quot;Open failed&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    fputs(&quot;Buffered I/O makes C fast.\\n&quot;, fp);</span></span>
<span class="line"><span>    fputs(&quot;fgets and fputs are line-based tools.\\n&quot;, fp);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    printf(&quot;Wrote to output.txt\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Buffered I/O makes C fast.</span></span>
<span class="line"><span>fgets and fputs are line-based tools.</span></span></code></pre></div><h4 id="why-fgets-is-safer-than-scanf-s" tabindex="-1">Why fgets Is Safer Than scanf(&quot;%s&quot;, …) <a class="header-anchor" href="#why-fgets-is-safer-than-scanf-s" aria-label="Permalink to &quot;Why fgets Is Safer Than scanf(&quot;%s&quot;, …)&quot;">​</a></h4><ul><li><code>fgets()</code> respects buffer boundaries</li><li>It reads spaces and tabs correctly</li><li>It prevents undefined behavior from overflows</li></ul><p>Avoid this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scanf(&quot;%s&quot;, buffer); // stops at first space and may overflow</span></span></code></pre></div><p>Prefer this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fgets(buffer, sizeof(buffer), stdin);</span></span></code></pre></div><h4 id="writing-to-stdout-or-stderr-with-fputs" tabindex="-1">Writing to stdout or stderr with fputs <a class="header-anchor" href="#writing-to-stdout-or-stderr-with-fputs" aria-label="Permalink to &quot;Writing to stdout or stderr with fputs&quot;">​</a></h4><p><code>fputs()</code> works on any output stream, not just files.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fputs(&quot;Message to screen.\\n&quot;, stdout);</span></span>
<span class="line"><span>fputs(&quot;Error to stderr!\\n&quot;, stderr);</span></span></code></pre></div><p>You can even redirect these in the shell:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./program &gt; result.txt 2&gt; error.log</span></span></code></pre></div><h4 id="reading-files-line-by-line" tabindex="-1">Reading Files Line by Line <a class="header-anchor" href="#reading-files-line-by-line" aria-label="Permalink to &quot;Reading Files Line by Line&quot;">​</a></h4><p>Here’s how to read a file safely using<code>fgets()</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *fp = fopen(&quot;poem.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        perror(&quot;Failed to open file&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    char line[200];</span></span>
<span class="line"><span>    while (fgets(line, sizeof(line), fp))</span></span>
<span class="line"><span>        printf(&quot;%s&quot;, line);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="tiny-code-copy-a-file" tabindex="-1">Tiny Code: Copy a File <a class="header-anchor" href="#tiny-code-copy-a-file" aria-label="Permalink to &quot;Tiny Code: Copy a File&quot;">​</a></h4><p>A minimal file copier using<code>fgets</code> and<code>fputs</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *in = fopen(&quot;input.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    FILE *out = fopen(&quot;copy.txt&quot;, &quot;w&quot;);</span></span>
<span class="line"><span>    if (!in || !out) {</span></span>
<span class="line"><span>        perror(&quot;File error&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    char buf[256];</span></span>
<span class="line"><span>    while (fgets(buf, sizeof(buf), in))</span></span>
<span class="line"><span>        fputs(buf, out);</span></span>
<span class="line"><span>    fclose(in);</span></span>
<span class="line"><span>    fclose(out);</span></span>
<span class="line"><span>    printf(&quot;Copied successfully.\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="buffer-flushing" tabindex="-1">Buffer Flushing <a class="header-anchor" href="#buffer-flushing" aria-label="Permalink to &quot;Buffer Flushing&quot;">​</a></h4><p>Sometimes you need to manually flush output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fflush(stdout);</span></span></code></pre></div><p>This is useful for interactive programs that must show messages immediately.</p><p>To disable buffering entirely (e.g., for logging):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setbuf(stdout, NULL);</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Buffered I/O balances speed and safety:</p><ul><li><code>fgets</code> protects against overflow</li><li><code>fputs</code> ensures efficient output</li><li>Buffering minimizes slow disk and console calls</li></ul><p>It’s what makes C both low-level and performant without forcing you to manage every byte yourself.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write a program that reads lines from stdin and writes them to a new file.</li><li>Count how many lines you read before EOF.</li><li>Print each line with line numbers using<code>fgets</code> and<code>printf</code>.</li><li>Experiment with buffer sizes, try 16 vs 256 bytes and note the performance difference.</li><li>Flush output after every line for an interactive logging program.</li></ol><p><code>fgets</code> and<code>fputs</code> give you a safe, line-based foundation for file and console I/O. Next, you’ll learn how to handle errors correctly using<code>errno</code>,<code>perror</code>, and<code>strerror</code>, essential tools for writing reliable system programs in C.</p>`,56)])])}const h=a(i,[["render",p]]);export{f as __pageData,h as default};
